/// Import all MyMoney data into Finara's database.
/// This replaces the default seed and populates real user data.
Future<void> importMyMoneyData(AppDatabase db) async {
  final log = AppLogger.instance;
  log.backup('MyMoney import started');

  // Check if already imported
  final existingAccounts = await db.accountsDao.getAllAccounts();
  if (existingAccounts.length >= 9) {
    log.backup(
      'MyMoney data already imported (${existingAccounts.length} accounts exist), skipping',
    );
    return;
  }

  try {
    // 1. Clear existing seed data
    log.backup('Clearing existing seed data...');
    await db.delete(db.transactions).go();
    await db.delete(db.budgets).go();
    await db.delete(db.categories).go();
    await db.delete(db.accounts).go();

    // 2. Insert accounts
    for (final acct in myMoneyAccounts) {
      await db.into(db.accounts).insert(acct);
    }
    log.backup('Imported ${myMoneyAccounts.length} accounts');

    // 3. Insert categories
    for (final cat in myMoneyCategories) {
      await db.into(db.categories).insert(cat);
    }
    log.backup('Imported ${myMoneyCategories.length} categories');

    // 4. Insert records
    int count = 0;
    for (final rec in myMoneyRecords) {
      await db.into(db.transactions).insert(rec);
      count++;
    }
    log.backup('Imported $count transaction records');

    // 5. Insert budgets
    for (final b in myMoneyBudgets) {
      await db.into(db.budgets).insert(b);
    }
    log.backup('Imported ${myMoneyBudgets.length} budgets');

    log.backup('MyMoney import completed successfully!');
  } catch (e, st) {
    log.error('MyMoney import failed', e, st);
    rethrow;
  }
}
